          ledger: 1,
          code: 1
        ),
        TigerBeetle::Transfer.new(
          id: transfer_4_id,
          debit_account_id: debit_account_id,
          credit_account_id: account_id,
          amount: 40,
          ledger: 1,
          code: 1
        )
      ]
    )
    transfers = @client.get_account_transfers(
      TigerBeetle::AccountFilter.new(
