    assert_equal(0, accounts_4[1].debits_pending)
    transfer_4_id = TigerBeetle.id
    transfer_results_4 = @client.create_transfers(
      [
        TigerBeetle::Transfer.new(
          id: transfer_4_id,
          debit_account_id: account_b_id,
