    )
    transfer_result_4 = transfer_results_4[0]
    assert_equal(TigerBeetle::CreateTransferStatus::CREATED, transfer_result_4.status)
    assert_operator(transfer_result_4.timestamp, :>, 0)
    accounts_5 = @client.lookup_accounts([account_a_id, account_b_id])
    assert_equal(2, accounts_5.length)
    assert_equal(account_a_id, accounts_5[0].id)
    assert_equal(150, accounts_5[0].credits_posted)
    assert_equal(50, accounts_5[0].credits_pending)
    assert_equal(0, accounts_5[0].debits_posted)
    assert_equal(0, accounts_5[0].debits_pending)
    assert_equal(account_b_id, accounts_5[1].id)
    assert_equal(0, accounts_5[1].credits_posted)
    assert_equal(0, accounts_5[1].credits_pending)
    assert_equal(150, accounts_5[1].debits_posted)
    assert_equal(50, accounts_5[1].debits_pending)
    sleep(1500 / 1000.0)
    accounts_6 = @client.lookup_accounts([account_a_id, account_b_id])
    assert_equal(2, accounts_6.length)
    assert_equal(account_a_id, accounts_6[0].id)
    assert_equal(150, accounts_6[0].credits_posted)
    assert_equal(0, accounts_6[0].credits_pending)
    assert_equal(0, accounts_6[0].debits_posted)
    assert_equal(0, accounts_6[0].debits_pending)
    assert_equal(account_b_id, accounts_6[1].id)
